import sys;sys.path.insert(0,__import__('os').path.dirname(__file__));from viet_chung import xuat
# Thủy mặc tập 6: Bạch Đằng 1288 (mã tm6), bản 2
S=[
(1,"Hàng trăm chiến thuyền giặc đang xuôi một dòng sông lớn, đuổi theo mấy chiếc thuyền nhỏ đang bỏ chạy phía trước."),
(1,"Nhưng những chiếc thuyền nhỏ ấy không hề chạy trốn. Chúng đang dẫn cả đoàn chiến thuyền vào một nơi đã được chuẩn bị từ trước."),
(1,"Đó là sông Bạch Đằng. Đoàn chiến thuyền là của Ô Mã Nhi, tướng nhà Nguyên, và ông sắp phải trả giá bằng cả hạm đội lẫn tự do của mình."),
(1,"Nhưng vì sao Ô Mã Nhi lại có mặt trên khúc sông ấy? Có hai điều đã đẩy ông tới đó: một đoàn thuyền lương, và một con sông được chọn sẵn."),
(2,"Ba năm trước, quân nhà Nguyên đã thua ở Đại Việt. Cuối năm một nghìn hai trăm tám mươi bảy, Thoát Hoan lại dẫn đại quân theo đường bộ tràn sang."),
(2,"Trước khi giặc tới, vua hỏi Trần Quốc Tuấn, tức Hưng Đạo Đại Vương, tình hình năm nay ra sao. Ông đáp: năm nay đánh giặc nhàn."),
(2,"Nhưng câu ấy nghe như để vua yên lòng, vì lần này giặc sang cả đường biển. Tướng Ô Mã Nhi dẫn chiến thuyền vượt biển, tiến vào vùng Đông Bắc."),
(2,"Theo sau là đoàn thuyền chở lương do Trương Văn Hổ chỉ huy. Đại quân trên bộ trông cả vào số lương ấy."),
(2,"Rồi đoàn chiến thuyền của Ô Mã Nhi đi trước, còn đoàn thuyền lương nặng nề thì đi chậm lại phía sau."),
(3,"Giữ vùng biển Vân Đồn lúc ấy là Phó tướng Trần Khánh Dư. Thoạt đầu, quân của ông đánh không lại đoàn chiến thuyền của Ô Mã Nhi."),
(3,"Chiến thuyền giặc đi qua, tưởng như đường biển đã mở. Nhưng rồi đoàn thuyền lương mới tới, và lần này Trần Khánh Dư đánh chặn được."),
(3,"Thế là quân giặc tan vỡ ngay tại Vân Đồn. Lương thực và khí giới bắt được nhiều không kể xiết, còn Trương Văn Hổ phải bỏ thuyền chạy về nước."),
(3,"Thuyền lương mất, đó là điều đầu tiên đẩy Ô Mã Nhi về phía Bạch Đằng. Nhưng hậu quả của nó phải ít lâu sau mới lộ ra hết."),
(3,"Trong khi đó, quân giặc trên bộ vẫn tiến về Thăng Long, và kinh thành lại bị bỏ trống thêm một lần."),
(4,"Nhưng chiếm thành xong, quân nhà Nguyên không tìm được lương. Thuyền lương thì không bao giờ tới."),
(4,"Thiếu ăn, quân giặc phải tỏa đi cướp bóc khắp nơi. Ô Mã Nhi còn kéo quân về Long Hưng, phá lăng mộ của vua Trần Thái Tông."),
(4,"Càng đi cướp, quân giặc càng bị đánh úp, càng mỏi mệt. Rồi mùa hè lại sắp tới, mùa mà ba năm trước quân nhà Nguyên đã khổ vì nóng và bệnh."),
(4,"Vì thế, đầu năm một nghìn hai trăm tám mươi tám, Thoát Hoan quyết định rút. Quân bộ theo đường Lạng Sơn, còn chiến thuyền theo sông Bạch Đằng ra biển."),
(4,"Điều thứ hai lộ ra từ đây. Con sông giặc phải đi qua chính là Bạch Đằng, nơi hơn ba trăm năm trước Ngô Quyền đã đánh tan quân Nam Hán."),
(5,"Trần Quốc Tuấn sai người đóng cọc xuống lòng sông Bạch Đằng, phủ cỏ lên trên. Khi thủy triều lên, nước phủ kín những hàng cọc ấy."),
(5,"Trước trận, ông chỉ xuống dòng sông mà thề: trận này không phá xong giặc Nguyên thì không về đến sông này nữa."),
(5,"Ngày mồng tám tháng Ba, đoàn chiến thuyền của Ô Mã Nhi tới khúc sông có cọc. Lúc ấy thủy triều đang lên, mặt nước mênh mông."),
(5,"Một toán thuyền nhỏ của Đại Việt ra đánh nhử rồi giả thua chạy. Quân giặc đuổi theo, đi sâu vào khúc sông đã chuẩn bị sẵn."),
(5,"Mọi việc tưởng như vẫn trong tay quân giặc. Rồi thủy triều rút xuống, những hàng cọc nhô lên, và thuyền giặc mắc cọc, vỡ, nghiêng ngả khắp lòng sông."),
(5,"Đúng lúc ấy, quân Đại Việt từ hai bên bờ và từ trên sông cùng đổ ra đánh. Thuyền giặc tiến không được, lùi cũng không xong."),
(5,"Ô Mã Nhi bị bắt sống, cùng các tướng Phàn Tiếp, Tích Lệ Cơ. Theo sử cũ, số thuyền giặc bị bắt hơn bốn trăm chiếc."),
(6,"Còn Thoát Hoan đi đường bộ cũng chẳng yên. Trên đường rút về Lạng Sơn, quân giặc liên tục bị chặn đánh và phải chạy trốn qua biên giới."),
(6,"Đó là lần cuối quân nhà Nguyên sang đánh Đại Việt. Hốt Tất Liệt về sau còn tính đánh tiếp, nhưng đến khi mất vẫn không đánh được."),
(6,"Sau chiến tranh, người ta tìm thấy một hòm thư xin hàng của những người trong triều từng lén liên lạc với giặc."),
(6,"Thượng hoàng Trần Thánh Tông không mở ra xem, sai đốt hết đi, để những người từng dao động được yên lòng."),
(6,"Câu đánh giặc nhàn giờ đã rõ nghĩa. Đạo quân ấy đánh xa nhà, sống nhờ thuyền lương, mất lương thì phải rút qua đúng con sông đã chờ sẵn."),
(6,"Mấy chiếc thuyền nhỏ bỏ chạy hôm ấy đã dẫn cả hạm đội nhà Nguyên vào chỗ chết trên sông Bạch Đằng. Cảm ơn bạn đã lắng nghe câu chuyện này."),
]
xuat(S,'tm6',181001)
